contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, bool callerIsOwner) public payable {
        address currentOwner = c.owner();

        bool reverted;
        bool success;

        if (callerIsOwner) {
            require(msg.sender == currentOwner);
            (success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
            if (!success) {
                reverted = true;
            } else {
                reverted = false;
            }
        } else {
            require(msg.sender != currentOwner);
            (success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
            if (!success) {
                reverted = true;
            } else {
                reverted = false;
            }
        }

        if (callerIsOwner) {
            assert(!reverted && c.owner() == newOwner);
        } else {
            assert(reverted && c.owner() == currentOwner);
        }
    }

    receive() external payable {}
}

